function booleanSql(key: string, column: string, spec: unknown): string {
	const operators = operatorsOf(key, spec, ["eq", "$ne"]);
	if (operators.length !== 1) { return refuse("unsupported_operator", `"${shown(key)}" (one operator)`); }
	const [name, operand] = operators[0];
	if (name === "$ne") {
		if (typeof operand !== "boolean") { return refuse("unsupported_value", `$ne on "${shown(key)}" (true or false is expected)`); }
		return `${column} IS DISTINCT FROM ${operand ? "TRUE" : "FALSE"}`;
	}

